local existing=storage:FindFirstChild('ChestChase_R123_Backup')
if existing then
 -- Same build pasted again: redo. A different build with the same backup name must never run the old one.
 -- Same build = Build attribute, or an Installer identical to this one (pastes before the attribute never set it).
 local installer=existing:FindFirstChild('Installer')
 local same=existing:GetAttribute('Build')=='3558ed9955213ceece07eb777d48a9ff8cc7a673c9a55be79b0b08af9b49f72a'or(installer~=nil and installer:IsA('ModuleScript')and sha256(installer.Source)=='3558ed9955213ceece07eb777d48a9ff8cc7a673c9a55be79b0b08af9b49f72a')
 assert(same,'[R123] An older [R123] backup is in ServerStorage. Undo it first: require(game.ServerStorage.ChestChase_R123_Backup.Installer)("undo") then delete ServerStorage.ChestChase_R123_Backup and paste this again. Nothing changed.')
 existing:SetAttribute('Build','3558ed9955213ceece07eb777d48a9ff8cc7a673c9a55be79b0b08af9b49f72a')
 require(existing:WaitForChild('Installer'))('install');return
end
